#include "app.h"
#include <cwchar>
struct InputProfile {std::wstring key;unsigned open=13,confirm=2,back=3,favorite=4;int deadzone=8000;};
namespace {std::vector<InputProfile> profiles;}
void loadControllerProfiles(){profiles.clear();const auto n=std::min(64u,GetPrivateProfileIntW(L"ControllerProfiles",L"Count",0,ini.c_str()));for(unsigned i=0;i<n;++i){auto section=L"ControllerProfile"+std::to_wstring(i);InputProfile p;p.key=readValue(section.c_str(),L"Key");p.open=GetPrivateProfileIntW(section.c_str(),L"Open",openButton,ini.c_str());p.confirm=GetPrivateProfileIntW(section.c_str(),L"Confirm",okButton,ini.c_str());p.back=GetPrivateProfileIntW(section.c_str(),L"Back",backButton,ini.c_str());p.favorite=GetPrivateProfileIntW(section.c_str(),L"Favorite",starButton,ini.c_str());p.deadzone=std::clamp(static_cast<int>(GetPrivateProfileIntW(section.c_str(),L"Deadzone",8000,ini.c_str())),0,20000);if(!p.key.empty())profiles.push_back(p);}}
std::wstring serializeControllerProfiles(){std::wstring s=L"[ControllerProfiles]\r\nCount="+std::to_wstring(profiles.size())+L"\r\n";for(size_t i=0;i<profiles.size();++i){auto sec=L"[ControllerProfile"+std::to_wstring(i)+L"]\r\n";const auto&p=profiles[i];s+=sec+L"Key=\""+p.key+L"\"\r\nOpen="+std::to_wstring(p.open)+L"\r\nConfirm="+std::to_wstring(p.confirm)+L"\r\nBack="+std::to_wstring(p.back)+L"\r\nFavorite="+std::to_wstring(p.favorite)+L"\r\nDeadzone="+std::to_wstring(p.deadzone)+L"\r\n";}return s;}

std::wstring activeProfileKey;
std::wstring currentControllerProfile(){return activeProfileKey;}
void useControllerProfile(const std::wstring& key){activeProfileKey=key;}
unsigned* profileBinding(int action){if(activeProfileKey.empty())return action==A_CAPTURE_OPEN?&openButton:action==A_CAPTURE_OK?&okButton:action==A_CAPTURE_BACK?&backButton:&starButton;auto it=std::find_if(profiles.begin(),profiles.end(),[](const auto&p){return p.key==activeProfileKey;});if(it==profiles.end()){profiles.push_back({});profiles.back().key=activeProfileKey;it=profiles.end()-1;}return action==A_CAPTURE_OPEN?&it->open:action==A_CAPTURE_OK?&it->confirm:action==A_CAPTURE_BACK?&it->back:&it->favorite;}
int profileDeadzone(){if(activeProfileKey.empty())return 8000;auto it=std::find_if(profiles.begin(),profiles.end(),[](const auto&p){return p.key==activeProfileKey;});return it==profiles.end()?8000:it->deadzone;}
void setProfileDeadzone(int value){if(activeProfileKey.empty())return;auto* ignored=profileBinding(A_CAPTURE_OPEN);(void)ignored;auto it=std::find_if(profiles.begin(),profiles.end(),[](const auto&p){return p.key==activeProfileKey;});if(it!=profiles.end())it->deadzone=std::clamp(value,0,20000);}
PadState calibratePad(PadState s,int deadzone){auto axis=[&](std::int16_t v){const int n=v,d=std::clamp(deadzone,0,20000),m=std::abs(n);if(m<=d)return static_cast<std::int16_t>(0);const int sign=n<0?-1:1;const int out=std::min(32767,(m-d)*32767/std::max(1,32767-d));return static_cast<std::int16_t>(sign*out);};s.lx=axis(s.lx);s.ly=axis(s.ly);s.rx=axis(s.rx);s.ry=axis(s.ry);return s;}
